# component identify excluding 2s and 0
R,C=10,10; seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  v=grid[r][c]
  if v not in (0,2) and (r,c) not in seen:
   st=[(r,c)]; seen.add((r,c)); comp=[]
   while st:
    x,y=st.pop();comp.append((x,y))
    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=a<R and 0<=b<C and grid[a][b]==v and (a,b) not in seen:seen.add((a,b));st.append((a,b))
   comps.append((v,comp))
comps
